<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';
const services=[{id:1,name:'Консультация',category:'Знакомство',duration:30,price:1500,description:'Обсудим ваш уход и составим индивидуальный план процедур.'},{id:2,name:'Уход за лицом',category:'Уход',duration:60,price:3500,description:'Очищение, увлажнение и уход, подобранный под потребности кожи.'},{id:3,name:'Чистка лица',category:'Очищение',duration:90,price:4500,description:'Процедура очищения. Подходящий метод определим на консультации.'},{id:4,name:'Массаж лица',category:'Массаж',duration:60,price:3000,description:'Мягкая работа с мышцами лица и время для восстановления.'}];
const view=ref('services'),selected=ref(services[1]),name=ref(''),phone=ref(''),time=ref(''),consent=ref(false),reminder=ref(true),bookings=ref([]),success=ref(null);
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i+1);return {key:dateKey(d),label:d.toLocaleDateString('ru-RU',{weekday:'short'}),number:d.getDate(),full:d.toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}});
const date=ref(days[0].key);
const slots=['10:00','11:30','13:00','14:30','16:00','17:30'];
const money=v=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(v);
const available=computed(()=>slots.filter(s=>!bookings.value.some(b=>{if(b.date!==date.value)return false;const mins=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);return mins(s)<mins(b.time)+b.service.duration&&mins(s)+selected.value.duration>mins(b.time)})));
function choose(s){selected.value=s;time.value='';success.value=null;view.value='booking'}
function submit(){if(!available.value.includes(time.value))return;const b={id:crypto.randomUUID(),service:selected.value,date:date.value,time:time.value,name:name.value,phone:phone.value,reminder:reminder.value};bookings.value.push(b);success.value=b;name.value='';phone.value='';time.value='';consent.value=false;}
const fullDate=d=>days.find(x=>x.key===d)?.full||d;
const toolsLifecycle=new AbortController();
onMounted(()=>{const context=document.modelContext;if(!context?.registerTool)return;try{Promise.resolve(context.registerTool({name:'start_demo_booking',description:'Открыть форму демо-записи на выбранную процедуру; запись не создаётся.',inputSchema:{type:'object',properties:{serviceId:{type:'integer',enum:[1,2,3,4]}},required:['serviceId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const service=services.find(s=>s.id===input?.serviceId);if(!service)throw new Error('Неизвестная процедура');choose(service);return {status:'form_opened',service:service.name};}},{signal:toolsLifecycle.signal})).catch(()=>{});}catch{}});
onUnmounted(()=>toolsLifecycle.abort());
</script>

<template>
 <div class="demo">Демонстрационный сайт · процедуры и цены для примера · записи не отправляются</div>
 <header><a class="brand" href="#" @click.prevent="view='services'"><span class="mark">О</span><span>Ольга<small>КОСМЕТОЛОГИЯ</small></span></a><nav aria-label="Основная навигация"><button :class="{active:view==='services'}" @click="view='services'">Процедуры</button><button :class="{active:view==='booking'}" @click="success=null;view='booking'">Записаться</button><button :class="{active:view==='appointments'}" @click="view='appointments'">Демо-кабинет <span>{{bookings.length}}</span></button></nav></header>
 <main>
 <template v-if="view==='services'">
  <section class="intro"><div><p class="eyebrow">ВАШЕ ВРЕМЯ ДЛЯ СЕБЯ</p><h1>Забота о коже.<br><em>С вниманием к вам.</em></h1><p class="lead">Выберите процедуру и удобное время.<br>Если вы впервые — начните с консультации.</p><button class="primary" @click="choose(services[0])">Записаться на консультацию</button></div><aside class="note"><span class="note-number">01 /</span><h2>Начнём<br>со знакомства</h2><p>Уход начинается с понимания вашей кожи, привычек и пожеланий.</p><div class="note-footer">Ольга<span>Косметолог</span></div></aside></section>
  <section><div class="section-heading"><h2>Процедуры</h2><span>Выберите то, что подходит вам</span></div><div class="service-grid"><article v-for="(s,i) in services" :key="s.id"><div class="card-top"><span>{{s.category}}</span><span>0{{i+1}}</span></div><h3>{{s.name}}</h3><p>{{s.description}}</p><div class="service-bottom"><div><strong>{{money(s.price)}}</strong><small>{{s.duration}} минут</small></div><button @click="choose(s)" :aria-label="`Записаться: ${s.name}`">Выбрать</button></div></article></div></section>
 </template>
 <section v-else-if="view==='booking'" class="booking-layout"><div class="booking-summary"><p class="eyebrow">ОНЛАЙН-ЗАПИСЬ</p><h1>Время<br><em>для вашей кожи.</em></h1><p>Процедура, удобный день и несколько деталей — всё готово.</p><div class="summary-card"><small>ВАШ ВЫБОР</small><h2>{{selected.name}}</h2><p>{{selected.duration}} минут</p><strong>{{money(selected.price)}}</strong></div></div>
 <div v-if="success" class="form-card success" role="status"><span class="success-icon">✓</span><h2>Демо-запись создана</h2><p>{{success.name}}, ваша запись отображается в демо-кабинете.</p><div class="confirmation"><strong>{{success.service.name}}</strong><p>{{fullDate(success.date)}} · {{success.time}}</p><p>{{success.reminder?'Выбрано напоминание за 24 часа.':'Напоминание не выбрано.'}}</p></div><p class="muted">Это прототип: Ольга не получила запись, сообщение не будет отправлено. Данные исчезнут после обновления страницы.</p><button class="primary" @click="view='appointments'">Посмотреть запись</button></div>
 <form v-else class="form-card" @submit.prevent="submit"><h2>Запись на процедуру</h2><label for="service">Процедура</label><select id="service" v-model="selected" @change="time='' "><option v-for="s in services" :value="s" :key="s.id">{{s.name}} · {{money(s.price)}}</option></select><label>Удобный день</label><div class="days"><button v-for="d in days" :key="d.key" type="button" :class="{chosen:date===d.key}" :aria-pressed="date===d.key" :aria-label="d.full" @click="date=d.key;time=''"><small>{{d.label}}</small><strong>{{d.number}}</strong></button></div><label>Время</label><div class="times"><button v-for="s in available" :key="s" type="button" :class="{chosen:time===s}" :aria-pressed="time===s" @click="time=s">{{s}}</button></div><p v-if="!available.length">На этот день свободного времени нет. Выберите другой день.</p><div class="fields"><div><label for="name">Ваше имя</label><input id="name" v-model.trim="name" required maxlength="60" autocomplete="given-name" placeholder="Как к вам обращаться"></div><div><label for="phone">Телефон</label><input id="phone" v-model="phone" required type="tel" pattern="[+0-9 ()-]{10,20}" autocomplete="tel" placeholder="+7 (999) 123-45-67"></div></div><label class="check"><input type="checkbox" v-model="reminder"> Напомнить за 24 часа (демонстрация)</label><label class="check"><input type="checkbox" v-model="consent" required> Я понимаю, что это демо, и использую вымышленные контактные данные.</label><button class="primary submit" :disabled="!time">Создать демо-запись</button><p class="form-note">Запись хранится только до обновления страницы.</p></form></section>
 <section v-else><p class="eyebrow">ДЕМО-КАБИНЕТ ОЛЬГИ</p><div class="section-heading"><h1>Записи</h1><button class="primary" @click="success=null;view='booking'">Новая запись</button></div><p class="muted">Предпросмотр кабинета. В рабочей версии доступ будет защищён входом.</p><div v-if="!bookings.length" class="empty"><h2>Пока нет записей</h2><p>Создайте пробную запись, чтобы увидеть расписание и напоминания.</p></div><div v-for="b in bookings" :key="b.id" class="appointment"><div class="appointment-date"><strong>{{b.time}}</strong><span>{{fullDate(b.date)}}</span></div><div><h3>{{b.service.name}}</h3><p>{{b.name}} · {{b.phone}}</p><small>{{b.reminder?'Напоминание за 24 часа · не отправляется в демо':'Без напоминания'}}</small></div><button class="cancel" @click="bookings=bookings.filter(x=>x.id!==b.id)">Отменить демо-запись</button></div></section>
 </main><footer><span>Ольга · косметология</span><span>Прототип для обсуждения с клиенткой</span></footer>
</template>
